// AscendC Sum kernel — reduction along the last dimension
// Supports float32, float16, bfloat16
// Input: (outer_size, reduce_size) -> Output: (outer_size, 1)

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

// =========================================================================
// Sum Kernel — single strategy that handles all reduce sizes
// =========================================================================

template <typename dataType>
class SumKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t outerSize, int32_t reduceSize, int32_t blockSize,
        int32_t usedCoreNum, int32_t tasksPerCore, int32_t reduceTile,
        int64_t keepdim)
    {
        this->outerSize = outerSize;
        this->reduceSize = reduceSize;
        this->blockSize = blockSize;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->reduceTile = reduceTile;
        this->keepdim = keepdim;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(outerSize) * reduceSize);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), outerSize);

        if ASCEND_IS_AIV {
            subBlockSize_ = blockSize / AscendC::GetSubBlockNum();
            pipe.InitBuffer(xInQueue_, BUFFER_NUM, reduceTile * sizeof(dataType));
            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, sizeof(dataType));
            pipe.InitBuffer(accBuf_, subBlockSize_ * sizeof(float));
            pipe.InitBuffer(reduceBuf_, reduceTile * sizeof(float));
            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(xCastBuf_, reduceTile * sizeof(float));
                pipe.InitBuffer(yCastBuf_, subBlockSize_ * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= CeilDivU32(outerSize, blockSize)) {
                    continue;
                }

                for (int row = 0; row < subBlockSize_; ++row) {
                    const int rowIdx = bx * blockSize + subBlockIdx * subBlockSize_ + row;
                    if (rowIdx < outerSize) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline void CopyInX(int32_t rowIdx, int32_t colBase, int32_t validN)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * reduceSize + colBase], static_cast<uint32_t>(validN));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t rowIdx)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[rowIdx], yOutLocal_, 1);
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline float ComputeRowSum(int32_t rowIdx)
    {
        reduceLocal_ = reduceBuf_.Get<float>();
        sumLocal_ = sumBuf_.Get<float>();
        float rowSum = 0.0f;

        const int32_t reduceNum = (reduceSize + reduceTile - 1) / reduceTile;

        for (int ry = 0; ry < reduceNum; ++ry) {
            const int colBase = ry * reduceTile;
            const int validN = (colBase + reduceTile <= reduceSize) ? reduceTile : (reduceSize - colBase);

            CopyInX(rowIdx, colBase, validN);

            xInLocal_ = xInQueue_.DeQue<dataType>();
            if constexpr (std::is_same_v<dataType, float>) {
                AscendC::ReduceSum<float>(sumLocal_, xInLocal_, reduceLocal_, validN);
            } else {
                xLocal_ = xCastBuf_.Get<float>();
                AscendC::Cast(xLocal_, xInLocal_, AscendC::RoundMode::CAST_NONE, validN);
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::ReduceSum<float>(sumLocal_, xLocal_, reduceLocal_, validN);
            }
            rowSum += sumLocal_.GetValue(0);
            xInQueue_.FreeTensor(xInLocal_);
        }

        return rowSum;
    }

    __aicore__ inline void ProcessRow(int rowIdx)
    {
        float rowSum = ComputeRowSum(rowIdx);

        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::Duplicate(yOutLocal_, rowSum, 1);
        } else {
            yLocal_ = yCastBuf_.Get<float>();
            AscendC::Duplicate(yLocal_, rowSum, 1);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Cast(yOutLocal_, yLocal_, OutputRoundModeHelper<dataType>(), 1);
            AscendC::PipeBarrier<PIPE_V>();
        }
        yOutQueue_.EnQue(yOutLocal_);

        CopyOutY(rowIdx);
    }

private:
    int32_t outerSize = 0;
    int32_t reduceSize = 0;
    int32_t blockSize = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    int32_t reduceTile = 0;
    int64_t keepdim = 0;
    int subBlockSize_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<float> xLocal_;
    AscendC::LocalTensor<float> yLocal_;
    AscendC::LocalTensor<float> reduceLocal_;
    AscendC::LocalTensor<float> sumLocal_;
};

// =========================================================================
// Dtype dispatch helper
// =========================================================================

template <typename... Args>
__aicore__ inline void DispatchSum(
    GM_ADDR x, GM_ADDR y,
    int32_t outerSize, int32_t reduceSize, int32_t blockSize,
    int32_t usedCoreNum, int32_t tasksPerCore, int32_t reduceTile,
    int64_t keepdim, int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        SumKernel<float> kernel;
        kernel.Init(x, y, outerSize, reduceSize, blockSize, usedCoreNum, tasksPerCore, reduceTile, keepdim);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        SumKernel<half> kernel;
        kernel.Init(x, y, outerSize, reduceSize, blockSize, usedCoreNum, tasksPerCore, reduceTile, keepdim);
        kernel.Process();
    } else {
        SumKernel<bfloat16_t> kernel;
        kernel.Init(x, y, outerSize, reduceSize, blockSize, usedCoreNum, tasksPerCore, reduceTile, keepdim);
        kernel.Process();
    }
}

