extern "C" __global__ __aicore__ void sum(
    GM_ADDR x, GM_ADDR y,
    int32_t outerSize, int32_t reduceSize, int32_t blockSize,
    int32_t usedCoreNum, int32_t tasksPerCore, int32_t reduceTile,
    int64_t keepdim, int64_t dtypeFlag)
{
    DispatchSum(x, y, outerSize, reduceSize, blockSize, usedCoreNum, tasksPerCore, reduceTile, keepdim, dtypeFlag);
}
