#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_sum.h"

namespace ascend_kernel {

at::Tensor sum(const at::Tensor &self, at::IntArrayRef dim, bool keepdim) {
    // Input validation
    TORCH_CHECK(self.is_contiguous(), "sum: input must be contiguous");
    TORCH_CHECK(self.dtype() == at::kFloat || self.dtype() == at::kHalf || self.dtype() == at::kBFloat16,
                "sum: only float32, float16, bfloat16 are supported");

    int64_t ndim = self.dim();

    // Normalize dim to positive indices
    std::vector<int64_t> dims;
    if (dim.size() == 0) {
        // Sum all elements
        for (int64_t i = 0; i < ndim; ++i) {
            dims.push_back(i);
        }
    } else {
        for (auto d : dim) {
            int64_t pos_d = d >= 0 ? d : d + ndim;
            TORCH_CHECK(pos_d >= 0 && pos_d < ndim, "sum: dim out of range");
            dims.push_back(pos_d);
        }
    }

    // Sort dims in descending order for sequential reduction
    std::sort(dims.begin(), dims.end(), std::greater<int64_t>());

    // Compute output shape
    std::vector<int64_t> out_shape;
    std::vector<bool> reduce_mask(ndim, false);
    for (auto d : dims) {
        reduce_mask[d] = true;
    }
    for (int64_t i = 0; i < ndim; ++i) {
        if (reduce_mask[i]) {
            if (keepdim) {
                out_shape.push_back(1);
            }
        } else {
            out_shape.push_back(self.size(i));
        }
    }

    auto output = at::empty(out_shape, self.options());

    // For simplicity, handle single-dim reduction via reshape to 2D
    if (dims.size() == 1) {
        int64_t reduce_dim = dims[0];

        // Compute outer_size and reduce_size
        int64_t outer_size = 1;
        for (int64_t i = 0; i < ndim; ++i) {
            if (i != reduce_dim) {
                outer_size *= self.size(i);
            }
        }
        int64_t reduce_size = self.size(reduce_dim);

        // Reshape input to (outer_size, reduce_size)
        auto x_2d = self.reshape({outer_size, reduce_size});
        // Output is (outer_size,) - reshape later
        auto y_1d = at::empty({outer_size}, self.options());

        // Tiling parameters
        auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
        int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
        uint64_t ubSize = 0;
        ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

        int64_t blockSize = 64;
        int64_t outerNum = (outer_size + blockSize - 1) / blockSize;
        int64_t usedCoreNum = std::min(coreNum, outerNum);
        int64_t tasksPerCore = (outerNum + usedCoreNum - 1) / usedCoreNum;

        // Calculate reduceTile based on UB size
        // Need UB for: xInQueue (reduceTile * dtype), yOutQueue (dtype),
        // reduceBuf (reduceTile * fp32), sumBuf (16 * fp32), castBuf (reduceTile * fp32)
        // bufferCoefficient for fp16/bf16: ~16, for fp32: ~20
        int64_t dtypeSize = (self.dtype() == at::kFloat) ? 4 : 2;
        int64_t bufferCoefficient = (self.dtype() == at::kFloat) ? 20 : 16;
        int64_t reduceTile = static_cast<int64_t>(ubSize) / (bufferCoefficient * dtypeSize);
        reduceTile = (reduceTile / 32) * 32;  // 32B align
        if (reduceTile < 32) {
            reduceTile = 32;
        }
        if (reduceTile > reduce_size) {
            reduceTile = reduce_size;
        }

        // Dtype flag: 0=fp32, 1=fp16, 2=bf16
        int64_t dtypeFlag = 0;
        if (self.dtype() == at::kHalf) {
            dtypeFlag = 1;
        } else if (self.dtype() == at::kBFloat16) {
            dtypeFlag = 2;
        }

        int64_t keepdim_val = keepdim ? 1 : 0;

        // EXEC_KERNEL_CMD: all params must be lvalues
        int64_t outerSize_l = outer_size;
        int64_t reduceSize_l = reduce_size;
        int64_t blockSize_l = blockSize;
        int64_t usedCoreNum_l = usedCoreNum;
        int64_t tasksPerCore_l = tasksPerCore;
        int64_t reduceTile_l = reduceTile;
        int64_t keepdim_l = keepdim_val;
        int64_t dtypeFlag_l = dtypeFlag;

        EXEC_KERNEL_CMD(sum, usedCoreNum_l, x_2d, y_1d,
                        outerSize_l, reduceSize_l, blockSize_l,
                        usedCoreNum_l, tasksPerCore_l, reduceTile_l,
                        keepdim_l, dtypeFlag_l);

        // Reshape output to match expected shape
        if (keepdim) {
            std::vector<int64_t> reshape_shape;
            for (int64_t i = 0; i < ndim; ++i) {
                if (i == reduce_dim) {
                    reshape_shape.push_back(1);
                } else {
                    reshape_shape.push_back(self.size(i));
                }
            }
            y_1d = y_1d.reshape(reshape_shape);
        }
        output.copy_(y_1d.reshape(output.sizes()));
    } else {
        // Multi-dim reduction: fall back to sequential single-dim reductions
        auto temp = self;
        for (size_t i = 0; i < dims.size(); ++i) {
            int64_t d = dims[i];
            // Adjust dim for keepdim
            std::vector<int64_t> current_out_shape;
            std::vector<bool> current_reduce_mask(temp.dim(), false);
            current_reduce_mask[d] = true;
            for (int64_t j = 0; j < temp.dim(); ++j) {
                if (current_reduce_mask[j]) {
                    if (keepdim || i < dims.size() - 1) {
                        current_out_shape.push_back(1);
                    }
                } else {
                    current_out_shape.push_back(temp.size(j));
                }
            }

            auto temp_out = at::empty(current_out_shape, temp.options());

            int64_t outer_size = 1;
            for (int64_t j = 0; j < temp.dim(); ++j) {
                if (j != d) {
                    outer_size *= temp.size(j);
                }
            }
            int64_t reduce_size = temp.size(d);

            auto x_2d = temp.reshape({outer_size, reduce_size});
            auto y_1d = at::empty({outer_size}, temp.options());

            auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
            int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
            uint64_t ubSize = 0;
            ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

            int64_t blockSize = 64;
            int64_t outerNum = (outer_size + blockSize - 1) / blockSize;
            int64_t usedCoreNum = std::min(coreNum, outerNum);
            int64_t tasksPerCore = (outerNum + usedCoreNum - 1) / usedCoreNum;

            int64_t dtypeSize = (temp.dtype() == at::kFloat) ? 4 : 2;
            int64_t bufferCoefficient = (temp.dtype() == at::kFloat) ? 20 : 16;
            int64_t reduceTile = static_cast<int64_t>(ubSize) / (bufferCoefficient * dtypeSize);
            reduceTile = (reduceTile / 32) * 32;
            if (reduceTile < 32) {
                reduceTile = 32;
            }
            if (reduceTile > reduce_size) {
                reduceTile = reduce_size;
            }

            int64_t dtypeFlag = 0;
            if (temp.dtype() == at::kHalf) {
                dtypeFlag = 1;
            } else if (temp.dtype() == at::kBFloat16) {
                dtypeFlag = 2;
            }

            int64_t keepdim_val = (keepdim || i < dims.size() - 1) ? 1 : 0;

            int64_t outerSize_l = outer_size;
            int64_t reduceSize_l = reduce_size;
            int64_t blockSize_l = blockSize;
            int64_t usedCoreNum_l = usedCoreNum;
            int64_t tasksPerCore_l = tasksPerCore;
            int64_t reduceTile_l = reduceTile;
            int64_t keepdim_l = keepdim_val;
            int64_t dtypeFlag_l = dtypeFlag;

            EXEC_KERNEL_CMD(sum, usedCoreNum_l, x_2d, y_1d,
                            outerSize_l, reduceSize_l, blockSize_l,
                            usedCoreNum_l, tasksPerCore_l, reduceTile_l,
                            keepdim_l, dtypeFlag_l);

            temp = y_1d.reshape(temp_out.sizes());
        }
        output.copy_(temp.reshape(output.sizes()));
    }

    return output;
}

} // namespace ascend_kernel
