148	            xInLocal_ = xInQueue_.DeQue<dataType>();
149	            if constexpr (std::is_same_v<dataType, float>) {
150	                AscendC::ReduceSum<float>(sumLocal_, xInLocal_, reduceLocal_, validN);
151	            } else {
152	                xLocal_ = xCastBuf_.Get<float>();
153	                AscendC::Cast(xLocal_, xInLocal_, AscendC::RoundMode::CAST_NONE, validN);
154	                AscendC::PipeBarrier<PIPE_V>();
155	                AscendC::ReduceSum<float>(sumLocal_, xLocal_, reduceLocal_, validN);
156	            }
157	            rowSum += sumLocal_.GetValue(0);
158	            xInQueue_.FreeTensor(xInLocal_);
159	        }
160	
161	        return rowSum;
162	    }
163	
164	    __aicore__ inline void ProcessRow(int rowIdx)
165	    {
166	        float rowSum = ComputeRowSum(rowIdx);
167	
168	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
169	        if constexpr (std::is_same_v<dataType, float>) {
170	            AscendC::Duplicate(yOutLocal_, rowSum, 1);
171	        } else {
172	            yLocal_ = yCastBuf_.Get<float>();
173	            AscendC::Duplicate(yLocal_, rowSum, 1);
174	            AscendC::PipeBarrier<PIPE_V>();
175	            AscendC::Cast(yOutLocal_, yLocal_, OutputRoundModeHelper<dataType>(), 1);
176	            AscendC::PipeBarrier<PIPE_V>();
177	        }
178	        yOutQueue_.EnQue(yOutLocal_);
179	
180	        CopyOutY(rowIdx);
181	    }
