216	
217	template <typename... Args>
218	__aicore__ inline void DispatchSum(
219	    GM_ADDR x, GM_ADDR y,
220	    int32_t outerSize, int32_t reduceSize, int32_t blockSize,
221	    int32_t usedCoreNum, int32_t tasksPerCore, int32_t reduceTile,
222	    int64_t keepdim, int64_t dtypeFlag)
223	{
224	    if (dtypeFlag == 0) {
225	        SumKernel<float> kernel;
226	        kernel.Init(x, y, outerSize, reduceSize, blockSize, usedCoreNum, tasksPerCore, reduceTile, keepdim);
227	        kernel.Process();
228	    } else if (dtypeFlag == 1) {
229	        SumKernel<half> kernel;
230	        kernel.Init(x, y, outerSize, reduceSize, blockSize, usedCoreNum, tasksPerCore, reduceTile, keepdim);
231	        kernel.Process();
232	    } else {
233	        SumKernel<bfloat16_t> kernel;
234	        kernel.Init(x, y, outerSize, reduceSize, blockSize, usedCoreNum, tasksPerCore, reduceTile, keepdim);
235	        kernel.Process();
236	    }
237	}
