241	// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
242	// =========================================================================
243	
244	extern "C" __global__ __aicore__ void sum(
245	    GM_ADDR x, GM_ADDR y,
246	    int32_t outerSize, int32_t reduceSize, int32_t blockSize,
247	    int32_t usedCoreNum, int32_t tasksPerCore, int32_t reduceTile,
248	    int64_t keepdim, int64_t dtypeFlag)
249	{
250	    DispatchSum(x, y, outerSize, reduceSize, blockSize, usedCoreNum, tasksPerCore, reduceTile, keepdim, dtypeFlag);
251	}
