11	#include "torch_kernel_helper.h"
12	#include "tiling/platform/platform_ascendc.h"
13	#include "aclrtlaunch_sum.h"
14	
15	namespace ascend_kernel {
16	
17	at::Tensor sum(const at::Tensor &self, at::IntArrayRef dim, bool keepdim) {
18	    // Input validation
19	    TORCH_CHECK(self.is_contiguous(), "sum: input must be contiguous");
20	    TORCH_CHECK(self.dtype() == at::kFloat || self.dtype() == at::kHalf || self.dtype() == at::kBFloat16,
21	                "sum: only float32, float16, bfloat16 are supported");
22	
23	    int64_t ndim = self.dim();
24	
25	    // Normalize dim to positive indices
26	    std::vector<int64_t> dims;
27	    if (dim.size() == 0) {
28	        // Sum all elements
29	        for (int64_t i = 0; i < ndim; ++i) {
30	            dims.push_back(i);
31	        }
32	    } else {
33	        for (auto d : dim) {
34	            int64_t pos_d = d >= 0 ? d : d + ndim;
35	            TORCH_CHECK(pos_d >= 0 && pos_d < ndim, "sum: dim out of range");
36	            dims.push_back(pos_d);
37	        }
38	    }
39	
40	    // Sort dims in descending order for sequential reduction
41	    std::sort(dims.begin(), dims.end(), std::greater<int64_t>());
42	
43	    // Compute output shape
44	    std::vector<int64_t> out_shape;
45	    std::vector<bool> reduce_mask(ndim, false);
46	    for (auto d : dims) {
47	        reduce_mask[d] = true;
48	    }
49	    for (int64_t i = 0; i < ndim; ++i) {
50	        if (reduce_mask[i]) {
51	            if (keepdim) {
52	                out_shape.push_back(1);
53	            }
54	        } else {
55	            out_shape.push_back(self.size(i));
56	        }
57	    }
58	
59	    auto output = at::empty(out_shape, self.options());
60	
61	    // For simplicity, handle single-dim reduction via reshape to 2D
62	    if (dims.size() == 1) {
63	        int64_t reduce_dim = dims[0];
64	
65	        // Compute outer_size and reduce_size
66	        int64_t outer_size = 1;
67	        for (int64_t i = 0; i < ndim; ++i) {
68	            if (i != reduce_dim) {
69	                outer_size *= self.size(i);
70	            }
71	        }
72	        int64_t reduce_size = self.size(reduce_dim);
73	
74	        // Reshape input to (outer_size, reduce_size)
75	        auto x_2d = self.reshape({outer_size, reduce_size});
76	        // Output is (outer_size,) - reshape later
77	        auto y_1d = at::empty({outer_size}, self.options());
78	
79	        // Tiling parameters
80	        auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
81	        int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
82	        uint64_t ubSize = 0;
83	        ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
84	
85	        int64_t blockSize = 64;
86	        int64_t outerNum = (outer_size + blockSize - 1) / blockSize;
87	        int64_t usedCoreNum = std::min(coreNum, outerNum);
88	        int64_t tasksPerCore = (outerNum + usedCoreNum - 1) / usedCoreNum;
89	
90	        // Calculate reduceTile based on UB size
91	        // Need UB for: xInQueue (reduceTile * dtype), yOutQueue (dtype),
92	        // reduceBuf (reduceTile * fp32), sumBuf (16 * fp32), castBuf (reduceTile * fp32)
93	        // bufferCoefficient for fp16/bf16: ~16, for fp32: ~20
94	        int64_t dtypeSize = (self.dtype() == at::kFloat) ? 4 : 2;
95	        int64_t bufferCoefficient = (self.dtype() == at::kFloat) ? 20 : 16;
96	        int64_t reduceTile = static_cast<int64_t>(ubSize) / (bufferCoefficient * dtypeSize);
97	        reduceTile = (reduceTile / 32) * 32;  // 32B align
98	        if (reduceTile < 32) {
99	            reduceTile = 32;
100	        }
101	        if (reduceTile > reduce_size) {
102	            reduceTile = reduce_size;
103	        }
104	
105	        // Dtype flag: 0=fp32, 1=fp16, 2=bf16
106	        int64_t dtypeFlag = 0;
107	        if (self.dtype() == at::kHalf) {
108	            dtypeFlag = 1;
109	        } else if (self.dtype() == at::kBFloat16) {
110	            dtypeFlag = 2;
111	        }
112	
113	        int64_t keepdim_val = keepdim ? 1 : 0;
114	
115	        // EXEC_KERNEL_CMD: all params must be lvalues
116	        int64_t outerSize_l = outer_size;
117	        int64_t reduceSize_l = reduce_size;
118	        int64_t blockSize_l = blockSize;
119	        int64_t usedCoreNum_l = usedCoreNum;
120	        int64_t tasksPerCore_l = tasksPerCore;
121	        int64_t reduceTile_l = reduceTile;
122	        int64_t keepdim_l = keepdim_val;
123	        int64_t dtypeFlag_l = dtypeFlag;
124	
125	        EXEC_KERNEL_CMD(sum, usedCoreNum_l, x_2d, y_1d,
126	                        outerSize_l, reduceSize_l, blockSize_l,
127	                        usedCoreNum_l, tasksPerCore_l, reduceTile_l,
128	                        keepdim_l, dtypeFlag_l);
129	
130	        // Reshape output to match expected shape
131	        if (keepdim) {
132	            std::vector<int64_t> reshape_shape;
133	            for (int64_t i = 0; i < ndim; ++i) {
134	                if (i == reduce_dim) {
135	                    reshape_shape.push_back(1);
136	                } else {
137	                    reshape_shape.push_back(self.size(i));
138	                }
139	            }
140	            y_1d = y_1d.reshape(reshape_shape);
141	        }
142	        output.copy_(y_1d.reshape(output.sizes()));
143	    } else {
144	        // Multi-dim reduction: fall back to sequential single-dim reductions
145	        auto temp = self;
146	        for (size_t i = 0; i < dims.size(); ++i) {
147	            int64_t d = dims[i];
148	            // Adjust dim for keepdim
149	            std::vector<int64_t> current_out_shape;
150	            std::vector<bool> current_reduce_mask(temp.dim(), false);
151	            current_reduce_mask[d] = true;
152	            for (int64_t j = 0; j < temp.dim(); ++j) {
153	                if (current_reduce_mask[j]) {
154	                    if (keepdim || i < dims.size() - 1) {
155	                        current_out_shape.push_back(1);
156	                    }
157	                } else {
158	                    current_out_shape.push_back(temp.size(j));
159	                }
160	            }
161	
162	            auto temp_out = at::empty(current_out_shape, temp.options());
163	
164	            int64_t outer_size = 1;
165	            for (int64_t j = 0; j < temp.dim(); ++j) {
166	                if (j != d) {
167	                    outer_size *= temp.size(j);
168	                }
169	            }
170	            int64_t reduce_size = temp.size(d);
171	
172	            auto x_2d = temp.reshape({outer_size, reduce_size});
173	            auto y_1d = at::empty({outer_size}, temp.options());
174	
175	            auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
176	            int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
177	            uint64_t ubSize = 0;
178	            ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
179	
180	            int64_t blockSize = 64;
181	            int64_t outerNum = (outer_size + blockSize - 1) / blockSize;
182	            int64_t usedCoreNum = std::min(coreNum, outerNum);
183	            int64_t tasksPerCore = (outerNum + usedCoreNum - 1) / usedCoreNum;
184	
185	            int64_t dtypeSize = (temp.dtype() == at::kFloat) ? 4 : 2;
186	            int64_t bufferCoefficient = (temp.dtype() == at::kFloat) ? 20 : 16;
187	            int64_t reduceTile = static_cast<int64_t>(ubSize) / (bufferCoefficient * dtypeSize);
188	            reduceTile = (reduceTile / 32) * 32;
189	            if (reduceTile < 32) {
190	                reduceTile = 32;
191	            }
192	            if (reduceTile > reduce_size) {
193	                reduceTile = reduce_size;
194	            }
195	
196	            int64_t dtypeFlag = 0;
197	            if (temp.dtype() == at::kHalf) {
198	                dtypeFlag = 1;
199	            } else if (temp.dtype() == at::kBFloat16) {
200	                dtypeFlag = 2;
201	            }
202	
203	            int64_t keepdim_val = (keepdim || i < dims.size() - 1) ? 1 : 0;
204	
205	            int64_t outerSize_l = outer_size;
206	            int64_t reduceSize_l = reduce_size;
207	            int64_t blockSize_l = blockSize;
208	            int64_t usedCoreNum_l = usedCoreNum;
209	            int64_t tasksPerCore_l = tasksPerCore;
210	            int64_t reduceTile_l = reduceTile;
211	            int64_t keepdim_l = keepdim_val;
212	            int64_t dtypeFlag_l = dtypeFlag;
213	
214	            EXEC_KERNEL_CMD(sum, usedCoreNum_l, x_2d, y_1d,
215	                            outerSize_l, reduceSize_l, blockSize_l,
216	                            usedCoreNum_l, tasksPerCore_l, reduceTile_l,
217	                            keepdim_l, dtypeFlag_l);
218	
219	            temp = y_1d.reshape(temp_out.sizes());
220	        }
221	        output.copy_(temp.reshape(output.sizes()));
222	    }
223	
224	    return output;
225	}
226	
227	} // namespace ascend_kernel
