11	// AscendC Sum kernel — reduction along the last dimension
12	// Supports float32, float16, bfloat16
13	// Input: (outer_size, reduce_size) -> Output: (outer_size, 1)
14	
15	#include "kernel_operator.h"
16	
17	constexpr int32_t BUFFER_NUM = 2;
18	
19	// ---------------------------------------------------------------------------
20	// Inline helpers
21	// ---------------------------------------------------------------------------
22	
23	__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
24	{
25	    if (b == 0U) { return 0U; }
26	    return (a + b - 1U) / b;
27	}
28	
29	template <typename T>
30	__aicore__ inline void LoadGmToUb(
31	    AscendC::LocalTensor<T> &dst,
32	    AscendC::GlobalTensor<T> src,
33	    uint32_t count)
34	{
35	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
36	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
37	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
38	}
39	
40	template <typename T>
41	__aicore__ inline void StoreUbToGm(
42	    AscendC::GlobalTensor<T> dst,
43	    AscendC::LocalTensor<T> &src,
44	    uint32_t count)
45	{
46	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
47	    AscendC::DataCopyPad(dst, src, copyParams);
48	}
49	
50	template <typename T>
51	__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
52	{
53	    if constexpr (std::is_same_v<T, bfloat16_t>) {
54	        return AscendC::RoundMode::CAST_ROUND;
55	    }
56	    return AscendC::RoundMode::CAST_NONE;
57	}
58	
59	// =========================================================================
60	// Sum Kernel — single strategy that handles all reduce sizes
61	// =========================================================================
62	
63	template <typename dataType>
64	class SumKernel {
65	public:
66	    __aicore__ inline void Init(
67	        GM_ADDR x, GM_ADDR y,
68	        int32_t outerSize, int32_t reduceSize, int32_t blockSize,
69	        int32_t usedCoreNum, int32_t tasksPerCore, int32_t reduceTile,
70	        int64_t keepdim)
71	    {
72	        this->outerSize = outerSize;
73	        this->reduceSize = reduceSize;
74	        this->blockSize = blockSize;
75	        this->usedCoreNum = usedCoreNum;
76	        this->tasksPerCore = tasksPerCore;
77	        this->reduceTile = reduceTile;
78	        this->keepdim = keepdim;
79	
80	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(outerSize) * reduceSize);
81	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), outerSize);
82	
83	        if ASCEND_IS_AIV {
84	            subBlockSize_ = blockSize / AscendC::GetSubBlockNum();
85	            pipe.InitBuffer(xInQueue_, BUFFER_NUM, reduceTile * sizeof(dataType));
86	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, sizeof(dataType));
87	            pipe.InitBuffer(accBuf_, subBlockSize_ * sizeof(float));
88	            pipe.InitBuffer(reduceBuf_, 2 * reduceTile * sizeof(float));
89	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
90	            if constexpr (!std::is_same_v<dataType, float>) {
91	                pipe.InitBuffer(xCastBuf_, reduceTile * sizeof(float));
92	                pipe.InitBuffer(yCastBuf_, subBlockSize_ * sizeof(float));
93	            }
94	        }
95	    }
96	
97	    __aicore__ inline void Process()
98	    {
99	        if ASCEND_IS_AIV {
100	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
101	            const int subBlockIdx = AscendC::GetSubBlockIdx();
102	
103	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
104	                const int bx = coreIdx * tasksPerCore + localIdx;
105	                if (bx >= CeilDivU32(outerSize, blockSize)) {
106	                    continue;
107	                }
108	
109	                for (int row = 0; row < subBlockSize_; ++row) {
110	                    const int rowIdx = bx * blockSize + subBlockIdx * subBlockSize_ + row;
111	                    if (rowIdx < outerSize) {
112	                        ProcessRow(rowIdx);
113	                    }
114	                }
115	            }
116	        }
117	    }
118	
119	private:
120	    __aicore__ inline void CopyInX(int32_t rowIdx, int32_t colBase, int32_t validN)
121	    {
122	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
123	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * reduceSize + colBase], static_cast<uint32_t>(validN));
124	        xInQueue_.EnQue(xInLocal_);
125	    }
126	
127	    __aicore__ inline void CopyOutY(int32_t rowIdx)
128	    {
129	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
130	        StoreUbToGm(yGM_[rowIdx], yOutLocal_, 1);
131	        yOutQueue_.FreeTensor(yOutLocal_);
132	    }
133	
134	    __aicore__ inline float ComputeRowSum(int32_t rowIdx)
135	    {
136	        reduceLocal_ = reduceBuf_.Get<float>();
137	        sumLocal_ = sumBuf_.Get<float>();
138	        float rowSum = 0.0f;
139	
140	        const int32_t reduceNum = (reduceSize + reduceTile - 1) / reduceTile;
141	
142	        for (int ry = 0; ry < reduceNum; ++ry) {
143	            const int colBase = ry * reduceTile;
144	            const int validN = (colBase + reduceTile <= reduceSize) ? reduceTile : (reduceSize - colBase);
145	
146	            CopyInX(rowIdx, colBase, validN);
147	
148	            xInLocal_ = xInQueue_.DeQue<dataType>();
149	            if constexpr (std::is_same_v<dataType, float>) {
150	                // Clear sumLocal_ before ReduceSum
151	                AscendC::Duplicate(sumLocal_, 0.0f, 1);
152	                AscendC::PipeBarrier<PIPE_V>();
153	                AscendC::ReduceSum<float>(sumLocal_, xInLocal_, reduceLocal_, validN);
154	            } else {
155	                xLocal_ = xCastBuf_.Get<float>();
156	                AscendC::Cast(xLocal_, xInLocal_, AscendC::RoundMode::CAST_NONE, validN);
157	                AscendC::PipeBarrier<PIPE_V>();
158	                // Clear sumLocal_ before ReduceSum
159	                AscendC::Duplicate(sumLocal_, 0.0f, 1);
160	                AscendC::PipeBarrier<PIPE_V>();
161	                AscendC::ReduceSum<float>(sumLocal_, xLocal_, reduceLocal_, validN);
162	            }
163	            rowSum += sumLocal_.GetValue(0);
164	            xInQueue_.FreeTensor(xInLocal_);
165	        }
166	
167	        return rowSum;
168	    }
169	
170	    __aicore__ inline void ProcessRow(int rowIdx)
171	    {
172	        float rowSum = ComputeRowSum(rowIdx);
173	
174	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
175	        if constexpr (std::is_same_v<dataType, float>) {
176	            AscendC::Duplicate(yOutLocal_, rowSum, 1);
177	        } else {
178	            yLocal_ = yCastBuf_.Get<float>();
179	            AscendC::Duplicate(yLocal_, rowSum, 1);
180	            AscendC::PipeBarrier<PIPE_V>();
181	            AscendC::Cast(yOutLocal_, yLocal_, OutputRoundModeHelper<dataType>(), 1);
182	            AscendC::PipeBarrier<PIPE_V>();
183	        }
184	        yOutQueue_.EnQue(yOutLocal_);
185	
186	        CopyOutY(rowIdx);
187	    }
188	
189	private:
190	    int32_t outerSize = 0;
191	    int32_t reduceSize = 0;
192	    int32_t blockSize = 0;
193	    int32_t usedCoreNum = 0;
194	    int32_t tasksPerCore = 0;
195	    int32_t reduceTile = 0;
196	    int64_t keepdim = 0;
197	    int subBlockSize_ = 0;
198	
199	    AscendC::TPipe pipe;
200	    AscendC::GlobalTensor<dataType> xGM_;
201	    AscendC::GlobalTensor<dataType> yGM_;
202	
203	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
204	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
205	    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf_;
206	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
207	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
208	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
209	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
210	
211	    AscendC::LocalTensor<dataType> xInLocal_;
212	    AscendC::LocalTensor<dataType> yOutLocal_;
213	    AscendC::LocalTensor<float> xLocal_;
214	    AscendC::LocalTensor<float> yLocal_;
215	    AscendC::LocalTensor<float> reduceLocal_;
216	    AscendC::LocalTensor<float> sumLocal_;
217	};
218	
219	// =========================================================================
220	// Dtype dispatch helper
221	// =========================================================================
222	
223	template <typename... Args>
224	__aicore__ inline void DispatchSum(
225	    GM_ADDR x, GM_ADDR y,
226	    int32_t outerSize, int32_t reduceSize, int32_t blockSize,
227	    int32_t usedCoreNum, int32_t tasksPerCore, int32_t reduceTile,
228	    int64_t keepdim, int64_t dtypeFlag)
229	{
230	    if (dtypeFlag == 0) {
231	        SumKernel<float> kernel;
232	        kernel.Init(x, y, outerSize, reduceSize, blockSize, usedCoreNum, tasksPerCore, reduceTile, keepdim);
233	        kernel.Process();
234	    } else if (dtypeFlag == 1) {
235	        SumKernel<half> kernel;
236	        kernel.Init(x, y, outerSize, reduceSize, blockSize, usedCoreNum, tasksPerCore, reduceTile, keepdim);
237	        kernel.Process();
238	    } else {
239	        SumKernel<bfloat16_t> kernel;
240	        kernel.Init(x, y, outerSize, reduceSize, blockSize, usedCoreNum, tasksPerCore, reduceTile, keepdim);
241	        kernel.Process();
242	    }
243	}
244	
245	// =========================================================================
246	// Kernel entry point
247	// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
248	// =========================================================================
249	
250	extern "C" __global__ __aicore__ void sum(
251	    GM_ADDR x, GM_ADDR y,
252	    int32_t outerSize, int32_t reduceSize, int32_t blockSize,
253	    int32_t usedCoreNum, int32_t tasksPerCore, int32_t reduceTile,
254	    int64_t keepdim, int64_t dtypeFlag)
255	{
256	    DispatchSum(x, y, outerSize, reduceSize, blockSize, usedCoreNum, tasksPerCore, reduceTile, keepdim, dtypeFlag);
257	}
